 /**
  * Dual of multibase encoder and decoder.
  */
 export interface MultibaseCodec<Prefix extends string> {
   name: string
   prefix: Prefix
   encoder: MultibaseEncoder<Prefix>
   decoder: MultibaseDecoder<Prefix>
 }

